#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum AsciiDecodeOutcome {
    AsciiDecoded {
        text: String,
    },
    AsciiNonAscii {
        at: i64,
        octet: i64,
    },
}

#[derive(Debug, Clone, PartialEq, serde::Serialize, serde::Deserialize)]
#[serde(tag = "_variant")]
pub enum AsciiDecodeState {
    AsciiDecoding {
        at: i64,
        scalars: Rc<Vec<Char>>,
    },
    AsciiDecodeRefused {
        at: i64,
        octet: i64,
    },
}
impl AsciiDecodeState {
    pub fn at(&self) -> i64 {
        match self {
            AsciiDecodeState::AsciiDecoding { at: __val, .. } => __val.clone(),
            AsciiDecodeState::AsciiDecodeRefused { at: __val, .. } => __val.clone(),
        }
    }
}

pub fn ascii_octet(octet: i64) -> bool {
    ((octet.clone() >= 0) && (octet.clone() < 128))
}

pub fn ascii_decode_step(state: Rc<AsciiDecodeState>, octet: i64) -> Rc<AsciiDecodeState> {
    match (*state.clone()).clone() {
    AsciiDecodeState::AsciiDecodeRefused { at, octet: refused, .. } => Rc::new(AsciiDecodeState::AsciiDecodeRefused {
    at: at.clone(),
    octet: refused.clone(),
}),
    AsciiDecodeState::AsciiDecoding { at, scalars, .. } => if ascii_octet(octet.clone()) {
        Rc::new(AsciiDecodeState::AsciiDecoding {
    at: v1_rt::int_add(at.clone(), 1),
    scalars: crate::std_algebra::list_snoc_item(scalars.clone(), octet.clone()),
})
    } else {
        Rc::new(AsciiDecodeState::AsciiDecodeRefused {
    at: at.clone(),
    octet: octet.clone(),
})
    },
}
}

pub fn ascii_decode_octets(octets: Rc<Vec<i64>>) -> Rc<AsciiDecodeOutcome> {
    match (*octets.iter().cloned().fold(Rc::new(AsciiDecodeState::AsciiDecoding {
    at: 0,
    scalars: Rc::new(vec![]),
}), |st: Rc<AsciiDecodeState>, o: i64| ascii_decode_step(st, o.clone()))).clone() {
    AsciiDecodeState::AsciiDecoding { scalars, .. } => Rc::new(AsciiDecodeOutcome::AsciiDecoded {
    text: crate::std_coercion::unicode_scalar_fold(scalars.clone()),
}),
    AsciiDecodeState::AsciiDecodeRefused { at, octet, .. } => Rc::new(AsciiDecodeOutcome::AsciiNonAscii {
    at: at.clone(),
    octet: octet.clone(),
}),
}
}

